cards/1/code:
void OnClick()
{
    Show(GetData());   // GetData waits for the server: the thread stands still
}                      // the next click is picked up only after we return

cards/3/code:
// synchronous: the thread stands in GetData, clicks pile up
void OnClick()       { Show(GetData()); }

// asynchronous: while the request runs, the thread is free
async void OnClick() { var r = await GetDataAsync(); Show(r); }

cards/4/code:
async void OnClick()
{
    var r = await GetDataAsync(); // 1–2. request sent, the handler returned control
                                  // 3. the main thread handles other events
    Show(r);                      // 4–5. the continuation: from the queue, on the main thread again
}
